// Minimal re-implementation of Python argparse behavior for this program.
// Supports: --name value, --name=value, -h/--help, required options, int type.

import { basename } from 'node:path';

function pyInt(value) {
  // Mirrors Python's int(value) for base-10 string input.
  const s = String(value).trim();
  if (!/^[+-]?\d+$/.test(s)) {
    return null;
  }
  return parseInt(s, 10);
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog || basename(process.argv[1] || 'prog');
    this.options = []; // { name, metavar, required, type }
  }

  addArgument(name, { type = 'str', required = false } = {}) {
    const dest = name.replace(/^--/, '');
    this.options.push({ name, dest, metavar: dest.toUpperCase(), required, type });
  }

  usage() {
    const parts = this.options.map(
      (o) => `${o.required ? '' : '['}${o.name} ${o.metavar}${o.required ? '' : ']'}`,
    );
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  helpText() {
    const lines = [this.usage(), '', 'options:', '  -h, --help  show this help message and exit'];
    for (const o of this.options) {
      lines.push(`  ${o.name} ${o.metavar}`);
    }
    return lines.join('\n');
  }

  error(message) {
    console.error(this.usage());
    console.error(`${this.prog}: error: ${message}`);
    process.exit(2);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const result = {};
    const byName = new Map(this.options.map((o) => [o.name, o]));
    const seen = new Set();

    for (let i = 0; i < argv.length; i += 1) {
      let token = argv[i];
      if (token === '-h' || token === '--help') {
        console.log(this.helpText());
        process.exit(0);
      }
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }
      const opt = byName.get(token);
      if (!opt) {
        this.error(`unrecognized arguments: ${argv.slice(i).join(' ')}`);
      }
      let value = inlineValue;
      if (value === null) {
        i += 1;
        if (i >= argv.length) {
          this.error(`argument ${opt.name}: expected one argument`);
        }
        value = argv[i];
      }
      if (opt.type === 'int') {
        const parsed = pyInt(value);
        if (parsed === null) {
          this.error(`argument ${opt.name}: invalid int value: '${value}'`);
        }
        value = parsed;
      }
      result[opt.dest] = value;
      seen.add(opt.name);
    }

    const missing = this.options.filter((o) => o.required && !seen.has(o.name));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.map((o) => o.name).join(', ')}`,
      );
    }
    return result;
  }
}

