// Job class mirroring the observable behavior of schedule.Job.

export class Job {
  constructor(interval, scheduler = null) {
    this.interval = interval;
    this.unit = null;
    this.jobFunc = null;
    this.scheduler = scheduler;
  }

  // Matches Python: repr(job) -> Job(interval=1, unit=days, do=<lambda>, args=(), kwargs={})
  repr() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=<lambda>, args=(), kwargs={})`;
  }

  toString() {
    return this.repr();
  }

  // Make console.log(job) print the Python-style repr instead of an object dump.
  [Symbol.for('nodejs.util.inspect.custom')]() {
    return this.repr();
  }

  do(jobFunc) {
    this.jobFunc = jobFunc;
    if (this.scheduler) {
      this.scheduler.jobs.push(this);
    }
    return this;
  }
}

function unitGetter(unit, startDay = null) {
  return function applyUnit() {
    this.unit = unit;
    if (startDay !== null) {
      this.startDay = startDay;
    }
    return this;
  };
}

// Time unit properties: every(n).seconds / .minutes / .hours
Object.defineProperty(Job.prototype, 'seconds', { get: unitGetter('seconds') });
Object.defineProperty(Job.prototype, 'minutes', { get: unitGetter('minutes') });
Object.defineProperty(Job.prototype, 'hours', { get: unitGetter('hours') });

// every().day -> unit=days; every().week -> unit=weeks
Object.defineProperty(Job.prototype, 'day', { get: unitGetter('days') });
Object.defineProperty(Job.prototype, 'week', { get: unitGetter('weeks') });

// Weekday properties: every().monday ... every().sunday -> unit=weeks
for (const day of ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']) {
  Object.defineProperty(Job.prototype, day, { get: unitGetter('weeks', day) });
}

