// Scheduler mirroring the observable behavior of schedule.Scheduler
// and the module-level default scheduler (schedule.every / schedule.get_jobs).

import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    return new Job(interval, this);
  }

  getJobs() {
    return this.jobs.slice();
  }
}

// Default scheduler instance, mirroring schedule's module-level API.
export const defaultScheduler = new Scheduler();

export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

export function getJobs() {
  return defaultScheduler.getJobs();
}

