import { ArgumentParser } from './lib/argparse.mjs';
import * as schedule from './lib/schedule.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', { type: 'int', required: true });
parser.addArgument('--b', { type: 'int', required: true });
parser.addArgument('--c', { type: 'int', required: true });
const args = parser.parseArgs();

// 测试不同时间间隔的作业创建
const job1 = schedule.every(args.a).seconds.do(() => null); // 创建秒级作业
console.log(job1.interval);
const job2 = schedule.every(args.b).minutes.do(() => null); // 创建分钟作业
console.log(job2.interval);
const job3 = schedule.every(args.c).hours.do(() => null); // 创建小时作业
console.log(job3.interval);

// 创建更多组合作业
const job4 = schedule.every().day.do(() => null); // 创建每日作业
console.log(job4);
const job5 = schedule.every().week.do(() => null); // 创建每周作业
console.log(job5);
const job6 = schedule.every().monday.do(() => null); // 创建周一作业
console.log(job6);
const job7 = schedule.every().tuesday.do(() => null); // 创建周二作业
console.log(job7);
const job8 = schedule.every().wednesday.do(() => null); // 创建周三作业
console.log(job8);
const job9 = schedule.every().thursday.do(() => null); // 创建周四作业
console.log(job9);
const job10 = schedule.every().friday.do(() => null); // 创建周五作业
console.log(job10);
const job11 = schedule.every().saturday.do(() => null); // 创建周六作业
console.log(job11);
const job12 = schedule.every().sunday.do(() => null); // 创建周日作业
console.log(job12);

const allJobs = schedule.getJobs(); // 获取所有作业
console.log(allJobs.length);

